// th16_s3_w05 — TH16 v1.00a Stage 3 道中第 5 波（GirlA03 对称编队）
// 源入口 st03.ecl.txt MainSub03:1246-1266；依赖 GirlA03:463-469、
// GirlA03F:471-491、GirlA03_at:493-540。
// 掉落（dropMain/dropExtra/dropSeason）、ANM 与 PLAYSOUND 按公共口径省略。

const TIME_LIMIT: int = 1724;
const OPENING_BUFFER: int = 120;

// 源 etSprite(0, 6, 4)：TH16 type6、color4。
const TH16_RING_BALL: int = 448;
const RING_COLOR: int = 4;

// 源 MainSub03：5 轮、每轮 5 对；%A 从 -16 起每对 -40，x=±A，y=-64。
const FIRST_X: fx = -16fx;
const X_STEP: fx = 40fx;
const SPAWN_Y: fx = -64fx;

// 源 GirlA03_at：每波 etAim(0,2)、etCount(0,1,M)、etSpeed(0,2,1)，
// 角度 A 在 etOn 时从出弹口取一次；N=1 时各层同角。
// 源第二条 EX 是 PLAYSOUND，省略；第一条 EX type2(ANIM a=1) 的出生退位移
// -4*velocity 保留，体现在实际发弹坐标上。
sub fire_volley(layers: int) {
    var aim: angle = aim_player();
    var q: int = 0;
    while q < layers {
        var v: fx = 2fx;
        if layers > 1 { v = 2fx + (1fx - 2fx) * q / (layers - 1); }
        var back: fx = 4fx * v;
        _ = fire(TH16_RING_BALL, RING_COLOR,
                 $self_x - back * cos(aim), $self_y - back * sin(aim),
                 v, aim, none, none);
        q = q + 1;
    }
}

// 源 GirlA03_at 的难度分支：首发等待、发弹次数、间隔与层数。
async sub girl_attack() {
    var rank: int = global(GVAR_RANK);
    var pre: int = 100;
    var shots: int = 2;
    var gap: int = 100;
    var layers: int = 1;
    if rank == RANK_NORMAL { shots = 3; layers = 4; }
    if rank == RANK_HARD { pre = 50; shots = 4; layers = 4; }
    if rank == RANK_LUNATIC { pre = 30; shots = 5; gap = 60; layers = 4; }
    wait(pre);
    var n: int = 0;
    while n < shots {
        fire_volley(layers);
        wait(gap);
        n = n + 1;
    }
}

async sub girl_main() {
    set_invuln(65535);
    // 源 setHurtbox(24,24) / setHitbox(16,16)：普通圆形取第一值×0.5。
    set_hurtbox(12fx);
    set_hitbox(8fx);
    // 源 getAngle(%F2, 0.0f, -448.0f, FINAL_X, FINAL_Y)。
    var f2: angle = atan2($self_y + 448fx, $self_x);
    spawn girl_attack();
    // 源 moveVel(pi/2, 4.5) → 60 帧减速到 0 → 60 帧转向 F2、加速到 1.5。
    move_vel(0, 90deg, 4.5fx, EASE_LINEAR);
    move_speed(60, 0fx, EASE_LINEAR);
    wait(60);
    move_vel(60, f2, 1.5fx, EASE_LINEAR);
    wait(60);
    loop { wait(1000); }
}

// 源 MainSub03 排程：每对间隔 10 帧，每轮后 wait(80)。
async sub pattern() {
    wait(OPENING_BUFFER);
    var w: int = 0;
    while w < 5 {
        var x: fx = FIRST_X;
        var c: int = 0;
        while c < 5 {
            _ = spawn_enemy(x, SPAWN_Y, 100, 0, 1000, 0, girl_main);
            _ = spawn_enemy(0fx - x, SPAWN_Y, 100, 0, 1000, 0, girl_main);
            x = x - X_STEP;
            wait(10);
            c = c + 1;
        }
        wait(80);
        w = w + 1;
    }
}

async sub control() {
    set_invuln(65535);
    set_enemy_flag(ENEMY_NO_BODY, 1);
    phase_begin(0, pattern, TIME_LIMIT, 0);
    wait_spell();
    loop { wait(1); }
}

sub main() {
    _ = spawn_enemy(0fx, 0fx, 1000, 0, 0, 0, control);
    loop { wait(600); }
}
